import * as fs from "fs";

// 標準入力（左の「入力例」の内容）を 1 つの文字列として受け取り、
// 改行で区切って 1 行ずつの配列にする
const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 入力例 1 のとき:
//   input[0] は "5 3"
//   input[1] は "1 2 3 4 5"
//   input[2] は "1 3"
//   …（全 5 行。最後は input[4]）

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [n, q] = input[0].split(" ").map(Number);
const a = input[1].split(" ").map(Number);

// prefix[i] = A1 + … + Ai（prefix[0] = 0）
const prefix = new Array(n + 1).fill(0);
for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];

const out: number[] = [];
for (let i = 0; i < q; i++) {
  const [l, r] = input[2 + i].split(" ").map(Number);
  out.push(prefix[r] - prefix[l - 1]);
}
console.log(out.join("\n"));
